I have a similar config to [coconutbird](https://github.com/coconutbird), I guessed the 200k context limit right, but didn't know the exact output limit, I'm using his values now. Also I think newer models should be the same as their predecessors (Opus 4.7)


```
"augment": {
  "name": "Augment",
  "npm": "@ai-sdk/openai-compatible",
  "models": {
	"claude-haiku-4-5": {
	  "name": "Haiku 4.5",
	  "tool_call": true,
	  "modalities": {
		"input": ["text", "image"],
		"output": ["text"],
	  },
	  "limit": {
		"context": 200000,
		"output": 8192,
	  },
	},
	"claude-sonnet-4-6": {
	  "name": "Sonnet 4.6",
	  "tool_call": true,
	  "reasoning": true,
	  "modalities": {
		"input": ["text", "image"],
		"output": ["text"],
	  },
	  "limit": {
		"context": 200000,
		"output": 16384,
	  },
	},
	"claude-opus-4-6": {
	  "name": "Opus 4.6",
	  "tool_call": true,
	  "reasoning": true,
	  "modalities": {
		"input": ["text", "image"],
		"output": ["text"],
	  },
	  "limit": {
		"context": 200000,
		"output": 32768,
	  },
	},
	"claude-opus-4-7": {
	  "name": "Opus 4.7",
	  "tool_call": true,
	  "reasoning": true,
	  "modalities": {
		"input": ["text", "image"],
		"output": ["text"],
	  },
	  "limit": {
		"context": 200000,
		"output": 32768,
	  },
	},
	"gemini-3-1-pro-preview": {
	  "name": "Gemini 3.1 Pro Preview",
	  "tool_call": true,
	  "reasoning": true,
	  "modalities": {
		"input": ["text", "image"],
		"output": ["text"],
	  },
	  "limit": {
		"context": 200000,
		"output": 16384,
	  },
	},
	"gpt-5-4": {
	  "name": "GPT 5.4",
	  "tool_call": true,
	  "reasoning": true,
	  "modalities": {
		"input": ["text", "image"],
		"output": ["text"],
	  },
	  "limit": {
		"context": 200000,
		"output": 16384,
	  },
	},
  },
  "options": {
	"baseURL": "http://localhost:7888/v1",
	"timeout": 600000
  }
}
```
